// ignore_for_file: unused_element, unnecessary_cast


class CertificateConfigPublicKey {
  /// The format of the public key. Currently, only PEM format is supported.
  /// Possible values are: `KEY_TYPE_UNSPECIFIED`, `PEM`.
  final String format;
  /// Required. A public key. When this is specified in a request, the padding and encoding can be any of the options described by the respective 'KeyType' value. When this is generated by the service, it will always be an RFC 5280 SubjectPublicKeyInfo structure containing an algorithm identifier and a key. A base64-encoded string.
  final String? key;

  /// Creates a new [CertificateConfigPublicKey].
  /// [format] The format of the public key. Currently, only PEM format is supported.
  /// [key] Required. A public key. When this is specified in a request, the padding and encoding can be any of the options described by the respective 'KeyType' value. When this is generated by the service, it will always be an RFC 5280 SubjectPublicKeyInfo structure containing an algorithm identifier and a key. A base64-encoded string.
  CertificateConfigPublicKey({
    required this.format,
    this.key,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'format': format,
      'key': ?key,
    };
  }

  factory CertificateConfigPublicKey.fromMap(Map<String, dynamic> map) {
    return CertificateConfigPublicKey(
      format: map['format'] as String,
      key: map['key'] == null ? null : map['key'] as String,
    );
  }
}

